clear
clc

rng(12345);
N = 10000;
mu = 0;
sigma = 1;
x = mu + sigma*randn(N,1);

k = 0:9;
R = 1.2 * max(abs(x(1:10)));  

figure; %[output:99cba193]
stem(k, x(1:10)) %[output:99cba193]
ylim([-R R]); %[output:99cba193]

title('Ten Samples from a Normal Distribution') %[output:99cba193]
xlabel('Sample index, k') %[output:99cba193]
ylabel('Sample value, x(k)') %[output:99cba193]
grid("on"); %[output:99cba193]
legend("X \sim N(0,1)") %[output:99cba193]


